#include <iostream>
#include <string>
#include <vector>
#include <cstring>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

struct NTLMMessage {
    uint8_t signature[8];
    uint32_t message_type;
    std::vector<uint8_t> payload;
};

class ProxySession {
private:
    int client_fd_;
    int backend_fd_;
    std::string client_ip_;
    std::string backend_host_;
    bool authenticated_;
    uint32_t session_flags_;

    static constexpr uint32_t NTLMSSP_NEGOTIATE_SIGN = 0x00000010;
    static constexpr uint32_t NTLMSSP_NEGOTIATE_SEAL = 0x00000020;
    static constexpr uint32_t NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY = 0x00080000;
    static constexpr uint32_t NTLMSSP_REQUEST_TARGET = 0x00000004;

public:
    ProxySession(int client_fd, const std::string& client_ip)
        : client_fd_(client_fd), backend_fd_(-1),
          client_ip_(client_ip), authenticated_(false),
          session_flags_(0) {}

    ~ProxySession() {
        if (backend_fd_ >= 0) close(backend_fd_);
    }

    bool connect_backend(const std::string& host, uint16_t port) {
        backend_host_ = host;
        backend_fd_ = socket(AF_INET, SOCK_STREAM, 0);
        if (backend_fd_ < 0) return false;

        struct sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);
        // Validate the parsed address; inet_pton returns 1 on success.
        if (inet_pton(AF_INET, host.c_str(), &addr.sin_addr) != 1) {
            close(backend_fd_);
            backend_fd_ = -1;
            return false;
        }

        return connect(backend_fd_, (struct sockaddr*)&addr, sizeof(addr)) == 0;
    }

    bool validate_channel_binding(const NTLMMessage& msg) {
        // Channel binding validation for EPA (Extended Protection for Authentication)
        // Verify the client's channel binding matches our TLS session
        if (msg.payload.size() < 72) return false;

        // Extract AV_PAIR containing MsvAvChannelBindings
        size_t offset = 56; // After fixed AUTHENTICATE_MESSAGE fields
        while (offset + 4 <= msg.payload.size()) {
            uint16_t av_id;
            uint16_t av_len;
            std::memcpy(&av_id, msg.payload.data() + offset, sizeof(av_id));
            std::memcpy(&av_len, msg.payload.data() + offset + 2, sizeof(av_len));

            // Ensure the AV_PAIR body is fully contained within the payload
            // before treating it as valid or advancing past it.
            if (static_cast<size_t>(offset) + 4 + av_len > msg.payload.size()) {
                return false;
            }

            if (av_id == 0x000A) { // MsvAvChannelBindings
                // In a relay scenario, channel bindings would mismatch
                // but we only enforce this when session_flags_ includes signing
                return true; // Binding present, considered valid
            }
            if (av_id == 0x0000) break; // MsvAvEOL
            offset += 4 + av_len;
        }
        return true; // No channel binding required if not present
    }

    bool enforce_session_security(uint32_t negotiate_flags) {
        // Determine if we should enforce EPA based on negotiated flags
        // Critical: we check if the CLIENT requested signing
        // and use the CLIENT's flags for security decisions
        session_flags_ = negotiate_flags;

        bool require_epa = (negotiate_flags & NTLMSSP_NEGOTIATE_SIGN) &&
                          (negotiate_flags & NTLMSSP_NEGOTIATE_EXTENDED_SESSIONSECURITY);
        return require_epa;
    }

    int relay_authentication() {
        uint8_t buffer[4096];

        // Step 1: Receive NEGOTIATE from client
        ssize_t n = recv(client_fd_, buffer, sizeof(buffer), 0);
        if (n <= 0) return -1;

        NTLMMessage negotiate;
        negotiate.payload.assign(buffer, buffer + n);

        uint32_t client_flags = 0;
        if (n >= 16) {
            std::memcpy(&client_flags, buffer + 12, sizeof(client_flags));
        }

        // Step 2: Forward NEGOTIATE to backend
        // Here we pass through the negotiate flags unmodified
        send(backend_fd_, buffer, n, 0);

        // Step 3: Receive CHALLENGE from backend
        n = recv(backend_fd_, buffer, sizeof(buffer), 0);
        if (n <= 0) return -1;

        uint32_t server_flags = 0;
        if (n >= 24) {
            std::memcpy(&server_flags, buffer + 20, sizeof(server_flags));
        }

        // Step 4: Security decision - use client's flags for EPA enforcement
        // The client's negotiate flags determine our security posture
        bool epa_required = enforce_session_security(client_flags);

        // Step 5: Forward CHALLENGE to client
        send(client_fd_, buffer, n, 0);

        // Step 6: Receive AUTHENTICATE from client
        n = recv(client_fd_, buffer, sizeof(buffer), 0);
        if (n <= 0) return -1;

        NTLMMessage authenticate;
        authenticate.payload.assign(buffer, buffer + n);

        // Step 7: Validate channel bindings if EPA required
        if (epa_required) {
            if (!validate_channel_binding(authenticate)) {
                return -1;
            }
        }

        // Step 8: Forward AUTHENTICATE to backend
        send(backend_fd_, buffer, n, 0);

        // Step 9: Check backend response
        n = recv(backend_fd_, buffer, sizeof(buffer), 0);
        if (n > 0 && buffer[0] == 0x00) {
            authenticated_ = true;
        }

        return authenticated_ ? 0 : -1;
    }

    bool is_authenticated() const { return authenticated_; }
};

class NTLMProxy {
private:
    int listen_fd_;
    std::string backend_host_;
    uint16_t backend_port_;

public:
    NTLMProxy(const std::string& backend, uint16_t port)
        : listen_fd_(-1), backend_host_(backend), backend_port_(port) {}

    bool start(uint16_t listen_port) {
        listen_fd_ = socket(AF_INET, SOCK_STREAM, 0);
        if (listen_fd_ < 0) return false;

        int opt = 1;
        setsockopt(listen_fd_, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

        struct sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = INADDR_ANY;
        addr.sin_port = htons(listen_port);

        if (bind(listen_fd_, (struct sockaddr*)&addr, sizeof(addr)) < 0) return false;
        if (listen(listen_fd_, 128) < 0) return false;

        return true;
    }

    void accept_loop() {
        while (true) {
            struct sockaddr_in client_addr{};
            socklen_t len = sizeof(client_addr);
            int client_fd = accept(listen_fd_, (struct sockaddr*)&client_addr, &len);
            if (client_fd < 0) continue;

            char ip_str[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &client_addr.sin_addr, ip_str, sizeof(ip_str));

            ProxySession session(client_fd, ip_str);
            if (session.connect_backend(backend_host_, backend_port_)) {
                session.relay_authentication();
            }
            close(client_fd);
        }
    }
};

int main(int argc, char* argv[]) {
    if (argc < 4) {
        std::cerr << "Usage: " << argv[0] << " <listen_port> <backend_host> <backend_port>" << std::endl;
        return 1;
    }

    NTLMProxy proxy(argv[2], std::atoi(argv[3]));
    if (!proxy.start(std::atoi(argv[1]))) {
        std::cerr << "Failed to start proxy" << std::endl;
        return 1;
    }

    std::cout << "NTLM Proxy started on port " << argv[1] << std::endl;
    proxy.accept_loop();
    return 0;
}
